private boolean isCompleteBipartiteGraph(Graph<V,E> graph) {
    // Check if all vertices have even degree
    for (V vertex : graph.vertexSet()) {
        if (graph.degree(vertex) % 2 != 0) {
            return false;
        }
    }

    // Check if all edges are between vertices of different degrees
    for (E edge : graph.edgeSet()) {
        V vertex1 = graph.getEdgeSource(edge);
        V vertex2 = graph.getEdgeTarget(edge);
        if (vertex1 == vertex2 || graph.getVertexDegree(vertex1) == graph.getVertexDegree(vertex2)) {
            return false;
        }
    }

    return true;
}

